        EnvironmentFile = "/etc/default/prometheus";
        ExecStart = "${pkgs.prometheus}/bin/prometheus $ARGS";
        ExecReload = "${pkgs.coreutils}/bin/kill -HUP $MAINPID";
        TimeoutStopSec = "20s";
        SendSIGKILL = "no";
        AmbientCapabilities = "";
        CapabilityBoundingSet = "";
        DeviceAllow = "/dev/null rw";
        DevicePolicy = "strict";
        LimitMEMLOCK = 0;
        LimitNOFILE = 8192;
        LockPersonality = "yes";
        MemoryDenyWriteExecute = "yes";
        NoNewPrivileges = "yes";
        PrivateDevices = "yes";
        PrivateTmp = "yes";
        PrivateUsers = "yes";
        ProtectControlGroups = "yes";
        ProtectHome = "yes";
        ProtectKernelModules = "yes";
        ProtectKernelTunables = "yes";
        ProtectSystem = "full";
        RemoveIPC = "yes";
        RestrictNamespaces = "yes";
        RestrictRealtime = "yes";
        SystemCallArchitectures = "native";
      };
    };

    prometheus-alertmanager = {
      description = "Alertmanager for prometheus";
      wantedBy = [ "multi-user.target" ];
      serviceConfig = {
        Restart = "on-failure";
        User = "prometheus";
        EnvironmentFile = "/etc/default/prometheus-alertmanager";
        ExecStart = "${pkgs.prometheus-alertmanager}/bin/alertmanager $ARGS";
        ExecReload = "${pkgs.coreutils}/bin/kill -HUP $MAINPID";
        TimeoutStopSec = "20s";
        SendSIGKILL = "no";
      };
    };

    prometheus-blackbox-exporter = {
      description = "Blackbox exporter for Prometheus";
      wantedBy = [ "multi-user.target" ];
      serviceConfig = {
        Restart = "on-failure";
        User = "prometheus";
        EnvironmentFile = "/etc/default/prometheus-blackbox-exporter";
        ExecStart = "${pkgs.prometheus-blackbox-exporter}/bin/blackbox_exporter $ARGS";
        ExecReload = "${pkgs.coreutils}/bin/kill -HUP $MAINPID";
      };
    };

    prometheus-node-exporter = {
      description = "Prometheus exporter for machine metrics";
      wantedBy = [ "multi-user.target" ];
      serviceConfig = {
        Restart = "on-failure";
        User = "prometheus";
