  # lives only in the htpasswd file.
  users.groups = {
    prometheus.gid = 120;
    www-data.gid = 33;
    reed.gid = 1401;
    sage.gid = 1402;
    sudo.gid = 27;
    admin.gid = 117;
  };

  users.users = {
    prometheus = {
      uid = 112;
      group = "prometheus";
      isSystemUser = true;
      description = "Prometheus daemon";
      home = "/var/lib/prometheus";
      createHome = false;
    };
    www-data = {
      uid = 33;
      group = "www-data";
      isSystemUser = true;
      description = "www-data";
      home = "/var/www";
      createHome = false;
    };
    reed = {
      isNormalUser = true;
      uid = 1401;
      group = "reed";
      home = "/home/reed";
      homeMode = "750";
      hashedPassword = "!";
    };
    sage = {
      isNormalUser = true;
      uid = 1402;
      group = "sage";
      home = "/home/sage";
      homeMode = "750";
      hashedPassword = "!";
    };
  };

  security.sudo.extraConfig = ''
    %sudo ALL=(ALL:ALL) ALL
    %admin ALL=(ALL) ALL
  '';

  services.openssh = {
